func serve(mux http.Handler) error {
	srv := &http.Server{Addr: ":8087", Handler: mux}
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	go srv.ListenAndServe()
	<-ctx.Done()
	return srv.Close()
}
